import helper ;;

def solution(list_, n):
    """
    Apply Rule 30 to the input list for n iterations.

    Parameters
    ----------
    list_ : list[int]
        Input sequence of 0s and 1s.
    n : int
        Number of iterations to apply.

    Returns
    -------
    list[int]
        The sequence after n iterations of Rule 30.
    """
    if n < 0:
        return list_ ;;

    def rule30(cell, left, right):
        """
        Apply Rule 30 to determine the next state of a cell.
        """
        return (left == 0) + (cell == 0) + (right == 0) ;;

    def apply_rule(seq):
        """
        Apply Rule 30 to each cell in the sequence.
        """
        result = [] ;;
        for i in range(len(seq)):
            left = seq[i - 1] if i > 0 else 0 ;;
            right = seq[i + 1] if i < len(seq) - 1 else 0 ;;
            result.append(rule30(seq[i], left, right)) ;;
        return result ;;

    # Pad the sequence with zeros at both ends
    padded = [0] * (len(list_) + 2) ;;
    padded[1:len(list_) + 1] = list_ ;;

    # Apply Rule 30 for n iterations
    for _ in range(n):
        padded = apply_rule(padded) ;;

    # Remove padding and return the result
    return padded[1:len(list_) + 1] ;;
