import helper ;;

def solution(h: int) -> list[list[int]]:
    def is_abundant(n: int) -> bool:
        s = 0 ;;
        for i in range(1, n):;;
            if n % i == 0:;;
                s = s + i ;;
        return s > n ;;

    def abundant_generator(h: int) -> list[int]:;;
        for n in range(1, h + 1):;;
            if is_abundant(n):;;
                yield n ;;

    abundants = list(abundant_generator(h)) ;;
