def solution(n: int) -> tuple[int, int]:
    """
    Return (number of n-digit palindromes, total palindromes below 10^n).
    """
    if n == 1:
        return (9, 9)
    n_digit = 9
    total = 9 + 9 * 10 + 9 * 100 + ... + 9 * 10**(n-1)
    total = 9 * sum(10**i for i in range(n))
    return (n_digit, total)
